import copy
import json
from pathlib import Path

from mootdx.consts import CONFIG
from mootdx.logger import logger
from mootdx.utils import get_config_path

__all__ = ['clone', 'get', 'has', 'load_config', 'path', 'save', 'set', 'settings', 'setup', 'update']

_DEFAULT_SETTINGS = copy.deepcopy(CONFIG)
settings = copy.deepcopy(_DEFAULT_SETTINGS)

BASE = Path(__file__).parent.parent
CONF = Path(get_config_path('config.json'))


def _write_config(filepath: Path, options: dict) -> None:
    filepath.parent.mkdir(parents=True, exist_ok=True)
    filepath.write_text(json.dumps(options, indent=2, ensure_ascii=False), encoding='utf-8')


def load_config(config: str = 'config.json') -> dict:
    filepath = Path(get_config_path(config))

    if not filepath.exists():
        _write_config(filepath, clone())
        return clone()

    with filepath.open('r', encoding='utf-8') as fp:
        loaded = json.load(fp) or {}

    current = copy.deepcopy(_DEFAULT_SETTINGS)
    current.update(loaded)
    return current


def setup(config: str = 'config.json'):
    """
    加载配置文件到内存。缺少配置时仅写入默认配置，不主动进行网络探测。

    :return: bool，true 表示数据导入成功。
    """
    global settings
    global CONF

    CONF = Path(get_config_path(config))

    try:
        settings = load_config(config)
    except (json.JSONDecodeError, OSError, TypeError, ValueError) as exc:
        logger.warning(f'配置文件无效，已重置为默认配置: {CONF}')
        logger.debug(exc)
        settings = copy.deepcopy(_DEFAULT_SETTINGS)
        _write_config(CONF, settings)

    return bool(settings)


def has(key, value):
    return value in settings.get(key, {})


def set(key, value):  # noqa: A001
    settings[key] = value
    return value


def get(key, default=None):
    parts = key.split('.')
    current = settings.get(parts[0], default)

    for part in parts[1:]:
        if not isinstance(current, dict):
            return default
        current = current.get(part, default)

    return current


def path(key, value=None):
    return Path(BASE, settings.get(key), value)


def clone():
    return copy.deepcopy(settings)


def update(options):
    settings.update(options)
    return settings


def save(config: str = 'config.json') -> bool:
    _write_config(Path(get_config_path(config)), settings)
    return True

